    const team = new Map<number, string>();
    for (const [code, ids] of Object.entries(FRANCHISE_IDS)) for (const id of ids) team.set(id, code);
    const by = new Map<string, { year: number; code: string; balls: number }[]>();
    for (const r of rs) { const c = team.get(r.bt); if (!c) continue; const xs = by.get(r.name) ?? []; xs.push({ year: r.year, code: c, balls: r.balls }); by.set(r.name, xs); }
