    for (const [, xs] of by) {
      const firstYear = Math.min(...xs.map((x) => x.year));
      if (firstYear > 2024) continue; // need room for two later seasons
      const debutCode = xs.filter((x) => x.year === firstYear).sort((p, q) => q.balls - p.balls)[0].code;
      const seasons = new Map<number, number>();
      for (const x of xs.filter((x) => x.code === debutCode && x.year > firstYear)) seasons.set(x.year, (seasons.get(x.year) ?? 0) + x.balls);
      const regular = [...seasons.values()].filter((b) => b >= 120).length >= 2;
      const s = stats.get(debutCode) ?? { debut: 0, reg: 0 };
      s.debut++; if (regular) s.reg++;
      stats.set(debutCode, s);
    }
    const rows: Row[] = [...stats.entries()].map(([code, s]) => ({ franchise: code, debutants: s.debut, becameRegulars: s.reg, conversionPct: dp(pctOf(s.reg, s.debut)) })).sort((x, y) => (y.conversionPct as number) - (x.conversionPct as number));
