// ── 80. The Scout's Blind Spot ────────────────────────────────────────────────
const s80: SlotSpec = {
  n: 80,
  storyType: "explainer",
  build(a) {
    const lg = leagueRpb(a);
    const sql = `SELECT pl.name, ${YEAR()} year, MAX(CASE WHEN i.batting_team_id IN ${a.T} THEN 1 ELSE 0 END) mine, SUM(d.batter_runs) runs, SUM(CASE WHEN d.is_wide = 0 THEN 1 ELSE 0 END) balls
      FROM deliveries d JOIN innings i ON i.innings_id = d.innings_id JOIN matches m ON m.match_id = d.match_id JOIN players pl ON pl.player_id = d.batter_id WHERE ${REGULATION} GROUP BY pl.name, year`;
    const rs = a.rows<{ name: string; year: number; mine: number; runs: number; balls: number }>(sql);
    const idx = new Map(rs.map((r) => [`${r.name}|${r.year}`, r]));
    const rel = (r: { runs: number; balls: number; year: number }) => (r.runs / (r.balls * (lg.by.get(r.year) ?? 1))) * 100;
    const hot = rs.filter((r) => r.balls >= 30 && r.balls < 100 && rel(r) >= 120).map((r) => ({ r, next: idx.get(`${r.name}|${r.year + 1}`) })).filter((x) => x.next && x.next.balls >= 60);
    const big = rs.filter((r) => r.balls >= 250 && rel(r) >= 120).map((r) => ({ r, next: idx.get(`${r.name}|${r.year + 1}`) })).filter((x) => x.next && x.next.balls >= 60);
    const hotBefore = mean(hot.map((x) => rel(x.r))), hotAfter = mean(hot.map((x) => rel(x.next!)));
    const bigBefore = mean(big.map((x) => rel(x.r))), bigAfter = mean(big.map((x) => rel(x.next!)));
    a.table("bs-cmp", "Hot seasons and the season after", "Relative strike rate (100 = season average); hot = 120 or more", hot.length + big.length, "player-seasons", sql, [
      { sample: "Small sample (30–99 balls)", hotSeason: dp(hotBefore, 0), nextSeason: dp(hotAfter, 0), players: hot.length },
      { sample: "Large sample (250+ balls)", hotSeason: dp(bigBefore, 0), nextSeason: dp(bigAfter, 0), players: big.length },
    ]);
    const mineHot = hot.filter((x) => x.r.mine);
    const tok = {
      hn: a.int("bs-hn", hot.length, "Small-sample hot seasons with a following season of at least 60 balls", { filters: "30–99 balls, relative strike rate 120+", n: hot.length, nUnit: "player-seasons", sql, check: floor(hot.length, 20, "player-seasons") }),
      hb: a.num("bs-hb", hotBefore, "Average relative strike rate in those hot seasons", { unit: "index", filters: "As above", n: hot.length, nUnit: "player-seasons", sql, check: floor(hot.length, 20, "player-seasons") }, 0),
      ha: a.num("bs-ha", hotAfter, "Average relative strike rate the following season", { unit: "index", filters: "As above", n: hot.length, nUnit: "player-seasons", sql, check: floor(hot.length, 20, "player-seasons") }, 0),
      bb: a.num("bs-bb", bigBefore, "Average relative strike rate in large-sample hot seasons", { unit: "index", filters: "250+ balls, relative strike rate 120+", n: big.length, nUnit: "player-seasons", sql, check: floor(big.length, 5, "player-seasons") }, 0),
      ba: a.num("bs-ba", bigAfter, "Average relative strike rate the following season", { unit: "index", filters: "As above", n: big.length, nUnit: "player-seasons", sql, check: floor(big.length, 5, "player-seasons") }, 0),
      mine: a.int("bs-mine", mineHot.length, `Of the small-sample hot seasons, those for ${a.code}`, { filters: "As above", n: hot.length, nUnit: "player-seasons", sql, check: derived("count") }),
    };
    const keepHot = (hotAfter - 100) / Math.max(1, hotBefore - 100), keepBig = (bigAfter - 100) / Math.max(1, bigBefore - 100);
    const gap = keepBig - keepHot;
    const cmpWord = gap > 0.15 ? "much more" : gap > 0.05 ? "somewhat more" : gap < -0.05 ? "less" : "about as much";
    const share = a.pct("bs-keep", keepHot * 100, "Share of the small-sample advantage over average kept the next season", { filters: "Derived from the averages", n: hot.length, nUnit: "player-seasons", sql, check: derived("(after − 100) ÷ (before − 100)") }, 0);
    const shareBig = a.pct("bs-keep-big", keepBig * 100, "Share of the large-sample advantage kept the next season", { filters: "Derived from the averages", n: big.length, nUnit: "player-seasons", sql, check: derived("(after − 100) ÷ (before − 100)") }, 0);
    return {
      dek: `A batter who scores at a blistering rate from a handful of balls is the easiest player to over-rate. The IPL's history shows how far those small-sample stars fall back.`,
      excerpt: `Batters who scored far faster than average from fewer than a hundred balls kept only part of that edge the next season. Batters who did it over a full season kept ${cmpWord}. Hot seasons of any size regress, and small ones are the easiest to over-read.`,
      keyTakeaways: [
        `${tok.hn} small-sample hot seasons (thirty to ninety-nine balls) averaged ${tok.hb} relative strike rate, then ${tok.ha} the next season: ${share} of the edge kept.`,
        `Large-sample hot seasons (two hundred and fifty balls or more) averaged ${tok.bb}, then ${tok.ba}: ${shareBig} kept.`,
        `${tok.mine} of the small-sample hot seasons were for ${a.code}.`,
      ],
      sections: [
        { heading: "The Small-Sample Star", body: [
          `A few explosive innings can make a batter look like a star. Scouts know the numbers are noisy, but the pull of a strike rate far above average is strong.`,
          `CricField took every IPL batter season with thirty to ninety-nine balls and a strike rate at least twenty per cent above the season average, and looked at the next season.`,
        ] },
        { heading: "How Far They Fall", body: [
          `${tok.hn} such small-sample hot seasons averaged ${tok.hb} on a scale where the season average is one hundred. The following season they averaged ${tok.ha}: only ${share} of the edge over average was kept.`,
          `Batters with an equally hot season over two hundred and fifty balls or more averaged ${tok.bb} and then ${tok.ba}, keeping ${shareBig} of their edge.`,
        ], chartIds: ["bs-chart"] },
        { heading: `At ${a.code}`, body: [
          `${tok.mine} of the small-sample hot seasons were for ${a.name}. Each is a case where the numbers looked better than the evidence behind them.`,
          `{{hyp:shrink}}`,
        ] },
        { heading: "Why This Happens", body: [
          `Large-sample hot seasons kept ${cmpWord} of their edge than small-sample ones. ${gap <= 0.05 ? "Even a full season of hot form is a weak guide to the next, so every strike rate should be discounted towards the average." : "Volume of evidence matters, but even full seasons regress."}`,
          `Over a few dozen balls, luck in which deliveries go for six and which go to fielders dominates; over hundreds of balls, skill matters more. Some of the fall-back is bowlers adjusting to a new player. The Bayesian-shrinkage article in this series shows how to correct for it.`,
        ] },
        { heading: "CricField Verdict: Shrink Before You Spend", body: [
          `${a.name} should discount small-sample strike rates heavily towards the average before bidding.`,
          `A full season of evidence is worth far more than a hot month.`,
        ] },
      ],
      charts: [{ id: "bs-chart", type: "column", title: "Hot season vs next season", subtitle: "Relative strike rate (100 = season average)", table: "bs-cmp", xKey: "sample", series: [{ key: "hotSeason", label: "Hot season" }, { key: "nextSeason", label: "Next season" }], xLabel: "Sample size", unit: "index", takeaway: gap > 0.05 ? "Small-sample stars fall back further than full-season ones." : "Hot seasons of every size fall back sharply.", ariaLabel: "Grouped column chart comparing relative strike rate in hot seasons and the following season for small and large samples." }],
      hypotheses: [hyp("shrink", "shrinking each batter's strike rate towards the average in proportion to balls faced predicts next-season strike rate better than the raw figure.", "No shrinkage model has been fitted here.", "Fit an empirical-Bayes shrinkage and compare prediction errors for raw and shrunk strike rates.")],
      literalNumbers: [{ text: "120", reason: "Hot-season threshold stated in a table label." }, { text: "100", reason: "Index baseline (season average = 100)." }, { text: "30–99", reason: "Small-sample band stated in a table label." }, { text: "250", reason: "Large-sample threshold stated in a table label." }],
      players: [],
      seasons: ["2008–2026"],
      hero: { narrative: `A breakout ${a.name} batter.`, wanted: `${a.name} young batter.`, query: `${a.name} young batter` },
      related: [84, 87, 75],
      seo: { metaTitle: metaTitle(`The scout's blind spot: small-sample stars at ${a.code}`), metaDescription: metaDesc(`How far IPL batters who scored blisteringly from few balls fell back the next season, and what it means for ${a.poss} scouting.`) },
      methodology: `${METHOD} Relative strike rate = runs ÷ (balls × season-average runs per ball) × 100. Hot = 120 or more; next season requires at least 60 balls.`,
    };
  },
};

